1	//! Utilities for color font handling
2	
3	use std::io::Read;
4	
5	use ttf_parser::{GlyphId, RgbaColor};
6	use typst_syntax::Span;
7	use usvg::tiny_skia_path;
8	use xmlwriter::XmlWriter;
9	
10	use crate::foundations::Bytes;
11	use crate::layout::{Abs, Frame, FrameItem, Point, Rect, Size};
12	use crate::text::FontInstance;
13	use crate::visualize::{
14	    ExchangeFormat, FixedStroke, Geometry, Image, RasterImage, Shape, SvgImage,
15	};
16	
17	/// Whether this glyph should be rendered via simple outlining instead of via
18	/// `glyph_frame`.
19	pub fn should_outline(font: &FontInstance, glyph_id: GlyphId) -> bool {
20	    let ttf = font.ttf();
21	    (ttf.tables().glyf.is_some()
22	        || ttf.tables().cff.is_some()
23	        || ttf.tables().cff2.is_some())
24	        && !ttf
25	            .glyph_raster_image(glyph_id, u16::MAX)
26	            .is_some_and(|img| img.format == ttf_parser::RasterImageFormat::PNG)
27	        && !ttf.is_color_glyph(glyph_id)
28	        && ttf.glyph_svg_image(glyph_id).is_none()
29	}
30	
31	/// A frame that can draw a glyph.
32	#[derive(Clone)]
33	pub struct GlyphFrame {
34	    pub upem: Abs,
35	    pub item: GlyphFrameItem,
36	}
37	
38	impl GlyphFrame {
39	    /// The font unit square.
40	    pub fn size(&self) -> Size {
41	        Size::splat(self.upem)
42	    }
43	}
44	
45	impl From<GlyphFrame> for Frame {
46	    fn from(g: GlyphFrame) -> Self {
47	        let mut frame = Frame::soft(Size::splat(g.upem));
48	        match g.item {
49	            GlyphFrameItem::Tofu(pos, shape) => {
50	                frame.push(pos, FrameItem::Shape(shape, Span::detached()));
51	            }
52	            GlyphFrameItem::Image(pos, image, size) => {
53	                frame.push(pos, FrameItem::Image(image, size, Span::detached()));
54	            }
55	        }
56	        frame
57	    }
58	}
59	
60	/// The glyph item that is drawn.
61	#[derive(Clone)]
62	pub enum GlyphFrameItem {
63	    /// A fallback rectangle.
64	    Tofu(Point, Shape),
65	    /// An image glyph.
66	    Image(Point, Image, Size),
67	}
68	
69	impl GlyphFrameItem {
70	    /// The position of the glyph item inside the parent frame.
71	    pub fn pos(&self) -> Point {
72	        match *self {
73	            GlyphFrameItem::Tofu(pos, _) => pos,
74	            GlyphFrameItem::Image(pos, _, _) => pos,
75	        }
76	    }
77	}
78	
79	/// Returns a frame representing a glyph and whether it is a fallback tofu
80	/// frame.
81	///
82	/// Should only be called on glyphs for which [`should_outline`] returns false.
83	///
84	/// The glyphs are sized in font units, [`text.item.size`] is not taken into
85	/// account.
86	///
87	/// [`text.item.size`]: crate::text::TextItem::size
88	#[comemo::memoize]
89	pub fn glyph_frame(font: &FontInstance, glyph_id: u16) -> Option<GlyphFrame> {
90	    let upem = Abs::pt(font.units_per_em());
91	    let glyph_id = GlyphId(glyph_id);
92	
93	    if let Some(frame) = draw_glyph(font, upem, glyph_id) {
94	        return Some(frame);
95	    }
96	
97	    // Generate a fallback tofu if the glyph couldn't be drawn, unless it is
98	    // the space glyph. Then, an empty frame does the job. (This happens for
99	    // some rare CBDT fonts, which don't define a bitmap for the space, but
100	    // also don't have a glyf or CFF table.)
101	    let not_space = font.ttf().glyph_index(' ') != Some(glyph_id);
102	    not_space.then(|| draw_fallback_tofu(font, upem, glyph_id))
103	}
104	
105	/// Tries to draw a glyph.
106	fn draw_glyph(font: &FontInstance, upem: Abs, glyph_id: GlyphId) -> Option<GlyphFrame> {
107	    let ttf = font.ttf();
108	    let kind = if let Some(raster_image) = ttf
109	        .glyph_raster_image(glyph_id, u16::MAX)
110	        .filter(|img| img.format == ttf_parser::RasterImageFormat::PNG)
111	    {
112	        draw_raster_glyph(font, upem, raster_image)
113	    } else if ttf.is_color_glyph(glyph_id) {
114	        draw_colr_glyph(font, glyph_id)
115	    } else if ttf.glyph_svg_image(glyph_id).is_some() {
116	        draw_svg_glyph(font, glyph_id)
117	    } else {
118	        None
119	    };
120	
121	    kind.map(|kind| GlyphFrame { upem, item: kind })
122	}
123	
124	/// Draws a fallback tofu box with the advance width of the glyph.
125	fn draw_fallback_tofu(font: &FontInstance, upem: Abs, glyph_id: GlyphId) -> GlyphFrame {
126	    let advance = font
127	        .ttf()
128	        .glyph_hor_advance(glyph_id)
129	        .map(|advance| Abs::pt(advance as f64))
130	        .unwrap_or(upem / 3.0);
131	    let inset = 0.15 * advance;
132	    let height = 0.7 * upem;
133	    let pos = Point::new(inset, upem - height);
134	    let size = Size::new(advance - inset * 2.0, height);
135	    let thickness = upem / 20.0;
136	    let stroke = FixedStroke { thickness, ..Default::default() };
137	    let shape = Geometry::Rect(size).stroked(stroke);
138	    GlyphFrame { upem, item: GlyphFrameItem::Tofu(pos, shape) }
139	}
140	
141	/// Draws a raster glyph in a frame.
142	///
143	/// Supports only PNG images.
144	fn draw_raster_glyph(
145	    font: &FontInstance,
146	    upem: Abs,
147	    raster_image: ttf_parser::RasterGlyphImage,
148	) -> Option<GlyphFrameItem> {
149	    let data = Bytes::new(raster_image.data.to_vec());
150	    let image = Image::plain(RasterImage::plain(data, ExchangeFormat::Png).ok()?);
151	
152	    let scale = upem / raster_image.pixels_per_em as f64;
153	    let image_width = scale * image.width();
154	    let image_height = scale * image.height();
155	
156	    let x_offset = scale * raster_image.x as f64;
157	    let mut y_offset = scale * raster_image.y as f64;
158	    // Apple Color emoji doesn't provide offset information (or at least
159	    // not in a way ttf-parser understands), so we artificially shift their
160	    // baseline to make it look good.
161	    if font.info().family.to_lowercase() == "apple color emoji" {
162	        // This factor is just taken from krilla.
163	        y_offset -= 0.128 * upem;
164	    }
165	
166	    let position = Point::new(-x_offset, -(image_height + y_offset));
167	    let size = Size::new(image_width, image_height);
168	    Some(GlyphFrameItem::Image(position, image, size))
169	}
170	
171	/// Draws a glyph from the COLR table into the frame.
172	fn draw_colr_glyph(font: &FontInstance, glyph_id: GlyphId) -> Option<GlyphFrameItem> {
173	    let svg_string = colr_glyph_to_svg(font, glyph_id)?;
174	
175	    let ttf = font.ttf();
176	    let width = ttf.global_bounding_box().width() as f64;
177	    let height = ttf.global_bounding_box().height() as f64;
178	    let x_min = ttf.global_bounding_box().x_min as f64;
179	    let y_max = ttf.global_bounding_box().y_max as f64;
180	
181	    let data = Bytes::from_string(svg_string);
182	    let image = Image::plain(SvgImage::new(data).ok()?);
183	
184	    let position = Point::new(Abs::pt(x_min), Abs::pt(-y_max));
185	    let size = Size::new(Abs::pt(width), Abs::pt(height));
186	    Some(GlyphFrameItem::Image(position, image, size))
187	}
188	
189	/// Convert a COLR glyph into an SVG file.
190	fn colr_glyph_to_svg(font: &FontInstance, glyph_id: GlyphId) -> Option<String> {
191	    let mut svg = XmlWriter::new(xmlwriter::Options::default());
192	
193	    let ttf = font.ttf();
194	    let width = ttf.global_bounding_box().width() as f64;
195	    let height = ttf.global_bounding_box().height() as f64;
196	    let x_min = ttf.global_bounding_box().x_min as f64;
197	    let y_max = ttf.global_bounding_box().y_max as f64;
198	    let tx = -x_min;
199	    let ty = -y_max;
200	
201	    svg.start_element("svg");
202	    svg.write_attribute("xmlns", "http://www.w3.org/2000/svg");
203	    svg.write_attribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
204	    svg.write_attribute("width", &width);
205	    svg.write_attribute("height", &height);
206	    svg.write_attribute_fmt("viewBox", format_args!("0 0 {width} {height}"));
207	
208	    let mut path_buf = String::with_capacity(256);
209	    let gradient_index = 1;
210	    let clip_path_index = 1;
211	
212	    svg.start_element("g");
213	    svg.write_attribute_fmt(
214	        "transform",
215	        format_args!("matrix(1 0 0 -1 0 0) matrix(1 0 0 1 {tx} {ty})"),
216	    );
217	
218	    let mut glyph_painter = GlyphPainter {
219	        face: ttf,
220	        svg: &mut svg,
221	        path_buf: &mut path_buf,
222	        gradient_index,
223	        clip_path_index,
224	        palette_index: 0,
225	        transform: ttf_parser::Transform::default(),
226	        outline_transform: ttf_parser::Transform::default(),
227	        transforms_stack: vec![ttf_parser::Transform::default()],
228	    };
229	
230	    ttf.paint_color_glyph(glyph_id, 0, RgbaColor::new(0, 0, 0, 255), &mut glyph_painter)?;
231	    svg.end_element();
232	
233	    Some(svg.end_document())
234	}
235	
236	/// Draws an SVG glyph in a frame.
237	fn draw_svg_glyph(font: &FontInstance, glyph_id: GlyphId) -> Option<GlyphFrameItem> {
238	    // TODO: Our current conversion of the SVG table works for Twitter Color Emoji,
239	    // but might not work for others. See also: https://github.com/RazrFalcon/resvg/pull/776
240	    let mut data = font.ttf().glyph_svg_image(glyph_id)?.data;
241	
242	    // Decompress SVGZ.
243	    let mut decoded = vec![];
244	    if data.starts_with(&[0x1f, 0x8b]) {
245	        let mut decoder = flate2::read::GzDecoder::new(data);
246	        decoder.read_to_end(&mut decoded).ok()?;
247	        data = &decoded;
248	    }
249	
250	    // Parse and simplify the SVG.
251	    let xml = std::str::from_utf8(data).ok()?;
252	    let document = roxmltree::Document::parse(xml).ok()?;
253	    let opts = usvg::Options::default();
254	    let tree = usvg::Tree::from_xmltree(&document, &opts).ok()?;
255	    let mut data = tree.to_string(&usvg::WriteOptions {
256	        indent: usvg::Indent::None,
257	        attributes_indent: usvg::Indent::None,
258	        ..Default::default()
259	    });
260	
261	    // The SVG coordinates and the font coordinates are not the same: the Y axis
262	    // is mirrored. But the origin of the axes are the same (which means that
263	    // the horizontal axis in the SVG document corresponds to the baseline). See
264	    // the reference for more details:
265	    // https://learn.microsoft.com/en-us/typography/opentype/spec/svg#coordinate-systems-and-glyph-metrics
266	    //
267	    // Using this SVG directly can result in a cropped glyph. In order to avoid
268	    // clipping issues, we apply a translate transform so the top-left corner of
269	    // the bounding box is moved into the origin (0, 0) to make it fully fit
270	    // into the view port defined by `viewBox="0 0 width height"`, like a
271	    // conventional SVG.
272	    let bbox = tree.root().bounding_box();
273	    let view_box = Rect::new(
274	        Point::new(Abs::pt(bbox.left() as f64), Abs::pt(bbox.top() as f64)),
275	        Point::new(Abs::pt(bbox.right() as f64), Abs::pt(bbox.bottom() as f64)),
276	    );
277	    fixup_svg(&mut data, view_box);
278	
279	    let data = Bytes::from_string(data);
280	    let image = Image::plain(SvgImage::new(data).ok()?);
281	
282	    let position = Point::new(view_box.min.x, view_box.min.y);
283	    let size = view_box.size();
284	    Some(GlyphFrameItem::Image(position, image, size))
285	}
286	
287	/// Replace or insert the size attributes (viewBox, width and height), and
288	/// insert a group with a transform that translates the `viewBox` so that the
289	/// top-left point is at the origin (0, 0).
290	fn fixup_svg(svg: &mut String, view_box: Rect) {
291	    let mut viewbox_range = None;
292	    let mut width_range = None;
293	    let mut height_range = None;
294	
295	    let mut s = unscanny::Scanner::new(svg);
296	    s.eat_until("<svg");
297	    s.expect("<svg");
298	
299	    let svg_attr_start = s.cursor();
300	
301	    while !s.eat_if('>') && !s.done() {
302	        s.eat_whitespace();
303	        let start = s.cursor();
304	
305	        let attr_name = s.eat_until('=').trim();
306	        // Eat the equal sign and the quote.
307	        s.expect('=');
308	        s.eat_until('"');
309	        s.expect('"');
310	
311	        while !s.eat_if('"') && !s.done() {
312	            s.eat();
313	        }
314	
315	        match attr_name {
316	            "viewBox" => viewbox_range = Some(start..s.cursor()),
317	            "width" => width_range = Some(start..s.cursor()),
318	            "height" => height_range = Some(start..s.cursor()),
319	            _ => {}
320	        }
321	    }
322	
323	    let svg_body_start = s.cursor();
324	    let Some(svg_body_end) = svg.rfind("</svg>") else {
325	        return;
326	    };
327	
328	    svg.insert_str(svg_body_end, "</g>");
329	    svg.insert_str(
330	        svg_body_start,
331	        &format!(
332	            r#"<g transform="translate({} {})">"#,
333	            -view_box.min.x.to_pt(),
334	            -view_box.min.y.to_pt()
335	        ),
336	    );
337	
338	    let size = view_box.size();
339	    let mut edits = [
340	        (
341	            viewbox_range,
342	            format!("viewBox=\"0 0 {} {}\"", size.x.to_pt(), size.y.to_pt(),),
343	        ),
344	        (width_range, format!("width=\"{}\"", size.x.to_pt())),
345	        (height_range, format!("height=\"{}\"", size.y.to_pt())),
346	    ];
347	
348	    // Sort edits by ranges; missing ranges will be moved to the start.
349	    edits.sort_by_key(|(range, _)| range.clone().map(|r| r.start));
350	
351	    // Replace or insert the attribute. Iterate in reverse, so the modifying the
352	    // string doesn't affect the ranges of the edits that are applied later on.
353	    for (range, str) in edits.into_iter().rev() {
354	        if let Some(range) = range {
355	            svg.replace_range(range, &str);
356	        } else {
357	            svg.insert_str(svg_attr_start, &str);
358	            svg.insert(svg_attr_start, ' ');
359	        }
360	    }
361	}
362	
363	struct ColrBuilder<'a>(&'a mut String);
364	
365	impl ColrBuilder<'_> {
366	    fn finish(&mut self) {
367	        if !self.0.is_empty() {
368	            self.0.pop(); // remove trailing space
369	        }
370	    }
371	}
372	
373	impl ttf_parser::OutlineBuilder for ColrBuilder<'_> {
374	    fn move_to(&mut self, x: f32, y: f32) {
375	        use std::fmt::Write;
376	        write!(self.0, "M {x} {y} ").unwrap();
377	    }
378	
379	    fn line_to(&mut self, x: f32, y: f32) {
380	        use std::fmt::Write;
381	        write!(self.0, "L {x} {y} ").unwrap();
382	    }
383	
384	    fn quad_to(&mut self, x1: f32, y1: f32, x: f32, y: f32) {
385	        use std::fmt::Write;
386	        write!(self.0, "Q {x1} {y1} {x} {y} ").unwrap();
387	    }
388	
389	    fn curve_to(&mut self, x1: f32, y1: f32, x2: f32, y2: f32, x: f32, y: f32) {
390	        use std::fmt::Write;
391	        write!(self.0, "C {x1} {y1} {x2} {y2} {x} {y} ").unwrap();
392	    }
393	
394	    fn close(&mut self) {
395	        self.0.push_str("Z ");
396	    }
397	}
